(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const x1 = x+w1x, y1 = y+w1y;
  const w2x = Math.sin(x1*0.025+t*0.15)*8 + Math.cos(y1*0.02-t*0.12)*6;
  const w2y = Math.cos(y1*0.022-t*0.18)*8 + Math.sin(x1*0.018+t*0.2)*6;
  const sx = x1+w2x, sy = y1+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*70,120+Math.cos(t*0.65+4)*60,0.11,2.1,0.85],
    [400+Math.cos(t*0.55+2)*60,180+Math.sin(t*0.75+1)*50,0.085,1.8,1.0],
    [240+Math.sin(t*0.25)*160,120+Math.cos(t*0.45+2)*100,0.055,2.5,1.15]
  ];
  let aS=0,iS=0,hrm=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    hrm+=Math.sin(d*f*0.5-t*sp*0.8+3)*w*0.5;
  }
  const n=9,act=aS/n,inh=iS/n,h=hrm/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin((sx+sy)*0.12+t*2.5)*0.3+Math.sin((sx-sy)*0.1-t*2)*0.3)/2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.03-ang*5+t*0.9)*0.5)*0.35;
  const micro=Math.sin(sx*0.3+t*1.5)*Math.sin(sy*0.35-t*1.2)*0.15;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+h*0.2+micro)*2.2);
  const blend=reaction*0.7+cell*0.2+h*0.1,v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,42,88],[18,85,120],[25,140,135],[60,175,130],[180,195,80],[225,175,55],[220,120,60],[195,70,55],[160,45,70],[100,30,80],[50,20,65],[20,15,55],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const pulse=0.85+Math.sin(t*0.3)*0.05+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.0+(Math.abs(reaction)-0.65)*0.6:1.0;
  const warmth=Math.max(0,1-dist/200)*0.08;
  const lum=pulse*edge;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum+warmth*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum+warmth*20)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum-warmth*10)|0)
  ];
}
